pm.test('signin accepts a submission with email_or_username and password', function () {
  pm.expect(pm.response.code, 'expected the submission to proceed to authentication').to.not.equal(401);
});

pm.test('signin rejects a submission with no email_or_username and names the field', function () {
  pm.expect(pm.response.code).to.equal(401);
  const body = pm.response.json();
  pm.expect(body, 'response should name the email_or_username field').to.have.property('email_or_username');
});

pm.test('signin rejects a submission with no password and names the password field', function () {
  pm.expect(pm.response.code).to.equal(401);
  const body = pm.response.json();
  pm.expect(body).to.have.property('password');
});

pm.test('signin succeeds when the registered email is submitted in a different case', function () {
  pm.expect(pm.response.code).to.equal(200);
});

pm.test('signin succeeds when the registered username is submitted in a different case', function () {
  pm.expect(pm.response.code).to.equal(200);
});

pm.test('signin succeeds with a registered email and its correct password', function () {
  pm.expect(pm.response.code).to.equal(200);
});

pm.test('signin succeeds again for the same account via a different valid identifier (username)', function () {
  pm.expect(pm.response.code).to.equal(200);
});

pm.test('a successful signin returns HTTP 200 with a body of the form {token: ...}', function () {
  pm.expect(pm.response.code).to.equal(200);
  const body = pm.response.json();
  pm.expect(body).to.have.property('token');
  pm.expect(Object.keys(body)).to.eql(['token']);
});

pm.test('signin rejects an unregistered identifier and captures the response for the identical-rejection comparison', function () {
  pm.expect(pm.response.code).to.equal(401);
  pm.collectionVariables.set('unregisteredStatus', pm.response.code);
  pm.collectionVariables.set('unregisteredBody', pm.response.text());
});

pm.test('signin rejects a registered identifier with the wrong password', function () {
  pm.expect(pm.response.code).to.equal(401);
});

pm.test('an unregistered identifier and a wrong password produce identical rejections', function () {
  const unregisteredStatus = pm.collectionVariables.get('unregisteredStatus');
  const unregisteredBody = pm.collectionVariables.get('unregisteredBody');
  pm.expect(pm.response.code, 'status should match the unregistered-identifier rejection').to.equal(unregisteredStatus);
  pm.expect(pm.response.text(), 'body should match the unregistered-identifier rejection').to.equal(unregisteredBody);
});

pm.test('a rejected signin returns HTTP 401', function () {
  pm.expect(pm.response.code).to.equal(401);
});

pm.test('a rejected signin response never contains the submitted password', function () {
  pm.expect(pm.response.text()).to.not.include('WrongPassw0rd9');
});

pm.test('after 3 failed attempts, a 4th attempt with the correct password is still rejected', function () {
  pm.expect(pm.response.code, 'expected the account to still be locked out').to.equal(401);
});

pm.test('a signin with the correct password succeeds after only one prior failure (below the lockout threshold)', function () {
  pm.expect(pm.response.code).to.equal(200);
});
